<template>
    <div>
        <div class="projects-list">
            <div
                v-for="(project, index) in projects"
                :key="project.id"
                class="project-wrapper"
            >
                <h2 v-if="index === 0" :class="{ wide: true }">
                    Working experience
                </h2>
                <h2
                    v-else-if="index === 1"
                    style="max-height: fit-content"
                    :class="{ wide: true }"
                >
                    Game Projects
                </h2>

                <div
                    @click="showDetails(project)"
                    class="project-item"
                    :class="{ wide: project.isWide, high: project.isHigh }"
                >
                    <div
                        v-if="project.iconUrl"
                        class="project-item-image"
                        :style="{
                            'background-image': 'url(' + project.iconUrl + ')',
                        }"
                    ></div>
                    <p v-else class="project-item-placeholder">
                        Work in progress
                    </p>

                    <div
                        class="title-bar"
                        :style="{ 'background-color': project.accentColor }"
                    >
                        <div class="title-text">
                            {{ project.name }}
                            <br />
                            {{ project.iconDescription }}
                        </div>
                        <div class="title-text">
                            {{ project.extraIconDescription }}
                        </div>
                    </div>
                </div>
            </div>
        </div>

        <ProjectDetailsOverlay
            v-on:close="showPopup = false"
            :visible="showPopup"
            :title="popupTitle"
            :htmlContent="popupContent"
            :color="popupColor"
        />
    </div>
</template>

<script lang="ts">
import { defineComponent } from "vue";
import ProjectDetailsOverlay from "@/components/ProjectDetailsOverlay.vue";
import ProjectData from "@/data/ProjectData.ts";

export default defineComponent({
    name: "ProjectsList",
    components: { ProjectDetailsOverlay },
    props: {
        projects: {
            type: Array as () => ProjectData[],
            required: true,
        },
    },
    data() {
        return {
            showPopup: false,
            popupTitle: "" as string,
            popupColor: "" as string,
            popupContent: "" as string,
        };
    },
    methods: {
        showDetails(item: ProjectData) {
            this.popupTitle = item.name;
            this.popupColor = item.accentColor;
            this.popupContent = item.htmlDescription;
            this.showPopup = true;
            window.scrollTo(0, 0);
        },
    },
});
</script>

<style scoped>
.project-item {
    height: 300px;
    margin-bottom: 20px;
    width: 100%;
    cursor: pointer;
    position: relative;
    overflow: hidden;
}

.project-wrapper {
    display: contents;
}

.project-item-image {
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
    height: 100%;
    width: 100%;
    transition: all 0.2s;
}
.project-item-image:hover {
    -webkit-transform: scale(1.1);
    -ms-transform: scale(1.1);
    transform: scale(1.1);
}

.project-item:hover {
    filter: brightness(120%);
}

.project-item-placeholder {
    font-size: 3em;
    text-align: center;
    margin: 25% 0;
}

.title-bar {
    display: flex;
    justify-content: space-between;
    position: absolute;
    bottom: 0px;
    width: 100%;
    background-color: #222222;
}

.title-text {
    padding: 20px;
}

h2 {
    text-align: center;
    font-size: 2em;
}

@media only screen and (min-width: 620px) {
    .projects-list {
        max-width: 1200px;
        display: grid;
        margin: 0 auto;
        grid-template-columns: repeat(2, 1fr);
        grid-gap: 20px;
        grid-auto-rows: minmax(225px, auto);
    }

    .project-item {
        margin: 0px;
        height: 100%;
        width: 100%;
        grid-row-end: span 2;
    }

    .wide {
        grid-column-end: span 2;
    }

    .high {
        grid-row-end: span 3;
    }

    .title-text {
        padding: 30px 30px;
    }
}
</style>
